import json

lines = open('ios_crash.ips').readlines()
crash = json.loads(''.join(lines[1:]))

# Check lastExceptionBacktrace structure
leb = crash.get('lastExceptionBacktrace')
if leb:
    if isinstance(leb, list):
        print('lastExceptionBacktrace is a list of frames directly')
        # It's a list of frames
        used_images = crash.get('usedImages', [])
        dotnet_indices = set()
        dotnet_libs = ['libcoreclr', 'libmonosgen', 'libSystem.Native', 'libSystem.Globalization', 
                       'libSystem.Security.Cryptography', 'libSystem.IO.Compression', 'libSystem.Net.Security', 'SampleMAUI']
        for i, img in enumerate(used_images):
            name = img.get('name', '')
            for lib in dotnet_libs:
                if lib in name:
                    dotnet_indices.add(i)
                    break

        for j, frame in enumerate(leb):
            img_idx = frame.get('imageIndex', -1)
            if img_idx in dotnet_indices:
                img = used_images[img_idx]
                addr = img['base'] + frame['imageOffset']
                print(f\"  #{j}: {img['name']} @ 0x{addr:x} (offset 0x{frame['imageOffset']:x})\")
    elif isinstance(leb, dict):
        print(f'lastExceptionBacktrace keys: {list(leb.keys())}')
